// Port of Go `ls/lsutil/userpreferences_generated.go` (ts#64554: "Code
// generated by gen-preferences from tools/userPreferences.schema.json"). The
// three generated functions keep Go's shape and field order: `withConfig`
// (`with_config`), `applyRawPreferences` (`apply_raw_preferences`) and
// `MarshalJSONTo`. Go repeats each field type's handling inline; here it is
// one helper per type (`preference_int`, `preference_strings`, the
// `parse_preference_*` functions), applied the same way at every field.
//
// PORT: Go `int` is 64 bits. `maximum_hover_length` and `IndentStyle` hold
// it; the formatter's sizes (`base_indent_size`, `indent_size`, `tab_size`)
// are `i32`, as in the rest of the formatter, so a size outside `i32` wraps
// (Go would build an indentation string that long).

// PORT: Go `strings.ToLower` maps each rune with `unicode.ToLower`. Rust
// `str::to_lowercase` uses the full mapping of a newer Unicode and the
// final-sigma rule, which Go does not.
pub(super) fn strings_to_lower(s: &str) -> String {
    s.chars().map(unicode::to_lower).collect()
}

/// Go `int(value)` of a `float64` on amd64 (CVTTSD2SQ): toward zero in
/// range; out of range and NaN give `math.MinInt64`, where Rust's `as`
/// saturates.
fn float64_to_int(value: f64) -> i64 {
    // 2^63 is exact in f64; -2^63 itself converts to i64::MIN. NaN is in no
    // range.
    const LIMIT: f64 = 9_223_372_036_854_775_808.0;
    if !(-LIMIT..LIMIT).contains(&value) {
        return i64::MIN;
    }
    value as i64
}

/// Go `switch value := value.(type) { case int: ...; case float64: ... }` of
/// an int field: a JSON number as a Go `int`. PORT: a decoded `any` never
/// holds a Go `int`; every `LspAny` number is the `float64` case.
fn preference_int(value: &LspAny) -> Option<i64> {
    match value {
        LspAny::Number(value) => Some(float64_to_int(*value)),
        _ => None,
    }
}

/// Go `if values, ok := value.([]any); ok { ... }` of a `[]string` field: the
/// string items, the others dropped.
fn preference_strings(value: &LspAny) -> Option<Vec<String>> {
    let LspAny::Array(values) = value else {
        return None;
    };
    Some(
        values
            .iter()
            .filter_map(|value| match value {
                LspAny::String(value) => Some(value.clone()),
                _ => None,
            })
            .collect(),
    )
}

/// Go `if value, ok := getPreferenceConfigValue(config, paths...); ok { if
/// value != nil { ... } }` of `withConfig`.
fn config_value(config: &IndexMap<String, LspAny>, paths: &[&str]) -> Option<LspAny> {
    get_preference_config_value(config, paths).filter(|value| !matches!(value, LspAny::Null))
}

/// Go `string(p.ImportModuleSpecifierPreference)`.
fn import_module_specifier_preference_string(
    value: ImportModuleSpecifierPreference,
) -> &'static str {
    match value {
        ImportModuleSpecifierPreference::None => "",
        ImportModuleSpecifierPreference::Shortest => "shortest",
        ImportModuleSpecifierPreference::ProjectRelative => "project-relative",
        ImportModuleSpecifierPreference::Relative => "relative",
        ImportModuleSpecifierPreference::NonRelative => "non-relative",
    }
}

/// Go `string(p.ImportModuleSpecifierEnding)`.
fn import_module_specifier_ending_string(
    value: ImportModuleSpecifierEndingPreference,
) -> &'static str {
    match value {
        ImportModuleSpecifierEndingPreference::None => "",
        ImportModuleSpecifierEndingPreference::Auto => "auto",
        ImportModuleSpecifierEndingPreference::Minimal => "minimal",
        ImportModuleSpecifierEndingPreference::Index => "index",
        ImportModuleSpecifierEndingPreference::Js => "js",
    }
}

// Go: ls/lsutil/userpreferences_generated.go:179 parsePreferenceIncludeInlayParameterNameHints
fn parse_preference_include_inlay_parameter_name_hints(
    value: &LspAny,
) -> IncludeInlayParameterNameHints {
    if let LspAny::String(value) = value {
        match strings_to_lower(value).as_str() {
            "none" => return IncludeInlayParameterNameHints::NONE,
            "literals" => return IncludeInlayParameterNameHints::LITERALS,
            "all" => return IncludeInlayParameterNameHints::ALL,
            _ => {}
        }
    }
    IncludeInlayParameterNameHints::NONE
}

// Go: ls/lsutil/userpreferences_generated.go:193 parsePreferenceIndentStyle
fn parse_preference_indent_style(value: &LspAny) -> IndentStyle {
    if let LspAny::String(value) = value {
        match strings_to_lower(value).as_str() {
            "none" => return IndentStyle::NONE,
            "block" => return IndentStyle::BLOCK,
            "smart" => return IndentStyle::SMART,
            _ => {}
        }
    }
    if let Some(value) = preference_int(value) {
        return IndentStyle(value);
    }
    IndentStyle::SMART
}

